import pandas as pd, numpy as np, statsmodels.api as sm
from sklearn.model_selection import KFold
df = pd.read_csv('data.csv')
def make_X(data, deg=3):
    X = pd.DataFrame(index=data.index)
    X['dY_placebo']=data['dY_placebo']
    for d in range(1,deg+1): X[f'h{d}']=data['log_hist_days']**d
    for c in ['log_pre_gmv','orders','cat_share','tenure']: X[c]=data[c]
    for v in [1,2,3,4]: X[f'r{v}']=(data['region']==v).astype(float)
    for v in [1,2,3]: X[f't{v}']=(data['tier']==v).astype(float)
    return sm.add_constant(X)
for deg in [1,2,3,4,5]:
    Xall=make_X(df,deg)
    rY=sm.OLS(df['dY'],Xall).fit(); rD=sm.OLS(df['D'],Xall).fit()
    lin=sm.OLS(df['dY']-rY.predict(Xall),sm.add_constant(df['D']-rD.predict(Xall))).fit()
    print('deg',deg,'params',lin.params.values,'bse',lin.bse.values)
